#!/usr/bin/env pwsh
$featureDescription = "Integrated RAG Chatbot Development - Build and embed a Retrieval-Augmented Generation chatbot inside the Docusaurus book. Allow users to ask questions about book content with two modes: Global Search Mode for any content and User-Selected Text Mode for highlighted text only. Uses RAG pipeline with OpenAI/Gemini LLM, Cohere embeddings, Qdrant Cloud vector DB, FastAPI backend, Neon Postgres metadata storage. Text ingestion: load Markdown files, chunk into 200-400 tokens, store vectors and metadata. Retrieval: embed query with Cohere, similarity search in Qdrant, return top-k chunks. LLM: answer only from supplied context. API: /embed, /query, /chat, /selected-text endpoints. UI: Docusaurus plugin/React component, cyber/minimal theme, streaming, desktop + mobile. Constraints: token-efficient, avoid diagrams, deterministic and non-hallucinated, free-tier limits. Success: >85% accuracy, reliable selected text mode, <800ms latency, aligned UI, fully embedded."

.\.specify\scripts\powershell\create-new-feature.ps1 -Json -ShortName 'rag-chatbot' -Number 2 $featureDescription
